        var d = el('article', 'pack-card');
        d.appendChild(el('h4', null, p.id));
        d.appendChild(el('p', null, p.tag));
        var chips = el('div', 'pack-chips');
        (p.counts || []).forEach(function (c) { chips.appendChild(el('span', null, c)); });
        d.appendChild(chips);
        packs.appendChild(d);
      });

