+.adopt-result.on { opacity: 1; }
+
+/* --------------------------- fleet board --------------------------- */
+.fleet-board {
+  border: 1.5px solid var(--ink); border-radius: var(--radius); background: var(--paper);
+  padding: 20px; box-shadow: 0 2px 0 var(--ink);
+}
+.canon-bar {
+  display: flex; align-items: center; gap: 12px; padding: 10px 14px;
+  background: var(--ink); color: var(--paper); border-radius: 10px;
+  font-size: 0.9rem; position: relative; overflow: hidden;
+}
+.canon-bar .mono { background: none; border: none; color: var(--paper); }
+.canon-bar .mono b { color: #7fd4ac; }
+.clock { width: 26px; height: 26px; color: #7fd4ac; }
+.clock-hand { transform-origin: 22px 22px; animation: sweep 8s linear infinite; }
+@keyframes sweep { to { transform: rotate(360deg); } }
+.canon-pulse {
+  position: absolute; inset: 0; border-radius: 10px; pointer-events: none;
+  background: linear-gradient(100deg, transparent 30%, rgba(127, 212, 172, 0.35) 50%, transparent 70%);
+  transform: translateX(-100%);
+}
+.canon-pulse.go { animation: slide 1.2s ease-in-out; }
+@keyframes slide { to { transform: translateX(100%); } }
+
+.repo-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-top: 14px; }
+.repo-tile {
+  border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px;
+  font-family: var(--mono); font-size: 0.74rem; display: grid; gap: 3px;
+  transition: border-color 0.35s ease, background 0.35s ease;
+}
+.repo-tile .r-name { font-weight: 700; color: var(--ink); }
+.repo-tile .r-ref { color: var(--ink-soft); transition: color 0.35s ease; }
+.repo-tile.stale .r-ref { color: var(--amber); }
+.repo-tile.fresh { border-color: var(--accent); background: var(--accent-wash); }
