+.brand-footer { font-size: 1.15rem; }
+.footer-tag { font-family: var(--mono); font-size: 0.8rem; color: var(--ink-soft); margin-top: 8px; }
+.footer-links { display: flex; gap: 20px; flex-wrap: wrap; }
+.footer-links a { color: var(--ink-soft); text-decoration: none; font-size: 0.9rem; }
+.footer-links a:hover { color: var(--ink); }
+.footer-meta {
+  margin-top: 32px; padding-top: 20px; border-top: 1px solid var(--line);
+  display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap;
+  font-size: 0.8rem; color: var(--ink-soft);
+}
+.footer-meta p { max-width: 72ch; }
+
+/* ---------------------------- responsive --------------------------- */
+@media (max-width: 940px) {
+  .hero-grid, .mech-grid, .adopt-grid { grid-template-columns: 1fr; }
+  .mech-grid-flip > .mech-copy { order: 0; }
+  .why-grid { grid-template-columns: 1fr; }
+  .stats { grid-template-columns: repeat(2, 1fr); }
+  .spotlight { grid-template-columns: 1fr; }
+  .packs-grid { grid-template-columns: 1fr; }
+  .repo-grid { grid-template-columns: repeat(2, 1fr); }
+  .nav nav a:not(.nav-cta) { display: none; }
+  .updates li { grid-template-columns: 1fr; gap: 2px; }
+}
+
+/* -------------------------- reduced motion ------------------------- */
+@media (prefers-reduced-motion: reduce) {
+  html { scroll-behavior: auto; }
+  .reveal, #term-body .t-line { opacity: 1; transform: none; transition: none; }
